//! One-off repair (temporary) of the picture descriptions written while the DeepSeek upload cache
//! was keyed by the describer's constant image key: within one process, every vision call after
//! the first was sent the first call's upload, so its description is of the wrong picture.
//!
//! Runs inside `qbot run`, in the background, when `<data>/repair-images.request` exists, because
//! the platform connection is the only route to the original bytes. It:
//!
//! 1. finds every archived picture marker whose text is a description generated by a vision call
//!    that was not the first of its process (process boundaries are the restarts NapCat logged);
//!    the first call of each process is checked against its picture by the vision model;
//! 2. fetches the original bytes again, describes them with the fixed pipeline (content-keyed
//!    cache), and rewrites only that marker, only if it still holds the poisoned text;
//! 3. rebuilds the episodes whose target or context lines were rewritten, after undoing what
//!    those and all later episodes of the group contributed to facts, group knowledge and names,
//!    then applies the findings again in archive order.
//!
//! Every outcome is appended to `<data>/repair-images.jsonl`. The work is idempotent: a marker
//! no longer holding a poisoned description is not a candidate, and an episode created after its
//! lines were rewritten is not rebuilt. On success the request file is renamed `.done`.

use std::collections::{BTreeMap, BTreeSet};
use std::io::Write as _;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use futures_util::StreamExt;
use qbot_core::marker::fill;
use qbot_core::{Clock, GroupId, MediaKind, MessageId, SliceGrid};
use qbot_gateway::bridge::Bridge;
use qbot_llm::Provider;
use qbot_media::{Describer, Fetcher, LlmDescriber, MediaRef, clean_description};
use qbot_memory::EpisodeJobs;
use qbot_memory::identity::{EvidenceKind, EvidenceRecord, IdentityPolicy, confidence, status_for};
use qbot_store::{PgArchive, PgMediaCache};
use serde_json::json;
use sha2::{Digest, Sha256};
use sqlx::{PgPool, Row};

/// When each process that described pictures with the bug ended, in epoch milliseconds: the
/// restarts NapCat logged as a dropped reverse WebSocket, and the deploy of the fix.
const RESTARTS: [i64; 5] = [
    1_791_212_383_000, // 2026-10-05T14:59:43Z
    1_791_252_919_000, // 2026-10-06T02:15:19Z
    1_791_257_949_000, // 2026-10-06T03:39:09Z
    1_791_260_824_000, // 2026-10-06T04:27:04Z
    1_791_369_052_000, // 2026-10-07T10:30:52Z, the fix
];

const MAX_IMAGE_BYTES: u64 = 8 * 1024 * 1024;

pub struct Repair {
    pub pool: PgPool,
    pub archive: PgArchive,
    pub cache: PgMediaCache,
    pub fetcher: Arc<dyn Fetcher>,
    pub describer: Arc<dyn Describer>,
    pub vision: Arc<dyn Provider>,
    pub jobs: Arc<EpisodeJobs>,
    pub slices: SliceGrid,
    pub clock: Arc<dyn Clock>,
    pub bridge: Arc<Bridge>,
    pub data_dir: PathBuf,
}

#[derive(Debug, Clone)]
struct Candidate {
    group: GroupId,
    message: MessageId,
    ordinal: u64,
    index: usize,
    old: String,
    window: usize,
    head: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Outcome {
    Repaired,
    Accurate,
    Unrecoverable,
    Changed,
}

impl Repair {
    fn request(&self) -> PathBuf {
        self.data_dir.join("repair-images.request")
    }

    pub fn requested(&self) -> bool {
        self.request().exists()
    }

    fn log(&self, entry: serde_json::Value) {
        tracing::info!(%entry, "repair");
        let path = self.data_dir.join("repair-images.jsonl");
        let line = format!("{entry}\n");
        if let Err(error) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
            .and_then(|mut f| f.write_all(line.as_bytes()))
        {
            tracing::error!(%error, "repair: the log could not be written");
        }
    }

    pub async fn run(self) {
        for _ in 0..120 {
            if self.bridge.is_connected() {
                break;
            }
            tokio::time::sleep(Duration::from_secs(1)).await;
        }
        let started = self.clock.now().get();
        self.log(json!({"phase": "start", "at_ms": started}));
        let outcome = async {
            self.pictures().await?;
            self.memory().await
        }
        .await;
        match outcome {
            Ok(()) => {
                self.log(json!({"phase": "finished"}));
                let done = self.data_dir.join("repair-images.done");
                if let Err(error) = std::fs::rename(self.request(), done) {
                    tracing::error!(%error, "repair: the request file could not be renamed");
                }
            }
            Err(error) => {
                tracing::error!(%error, "repair: stopped; the request stays for another attempt");
                self.log(json!({"phase": "failed", "error": error}));
            }
        }
    }

    /// Markers whose text is a description from the buggy era, with the window of the vision call
    /// that generated it and whether that call was the first of its process.
    async fn candidates(&self) -> Result<Vec<Candidate>, String> {
        find_candidates(&self.pool).await
    }

    async fn pictures(&self) -> Result<(), String> {
        let candidates = self.candidates().await?;
        self.log(json!({"phase": "pictures", "candidates": candidates.len(),
            "heads": candidates.iter().filter(|c| c.head).count()}));
        let results: Vec<(Candidate, Outcome)> = futures_util::stream::iter(candidates)
            .map(|c| async move {
                let outcome = self.picture(&c).await;
                (c, outcome)
            })
            .buffer_unordered(4)
            .collect()
            .await;
        let count = |o| results.iter().filter(|(_, r)| *r == o).count();
        self.log(json!({"phase": "pictures done",
            "repaired": count(Outcome::Repaired), "accurate": count(Outcome::Accurate),
            "unrecoverable": count(Outcome::Unrecoverable), "changed": count(Outcome::Changed)}));
        Ok(())
    }

    /// Whether `old` describes the picture, by the vision model.
    async fn matches(&self, bytes: &[u8], old: &str) -> Option<bool> {
        let judge = LlmDescriber::new(
            self.vision.clone(),
            format!(
                "You check a picture description. Description: \"{old}\"\n\
                 Does this description describe the picture you are shown (the same picture, not \
                 merely a similar topic)? Answer with exactly one word: yes or no."
            ),
        );
        let answer = judge
            .describe(bytes, qbot_media::sniff_mime(bytes))
            .await
            .ok()?
            .to_lowercase();
        if answer.starts_with("yes") {
            Some(true)
        } else if answer.starts_with("no") {
            Some(false)
        } else {
            None
        }
    }

    async fn picture(&self, c: &Candidate) -> Outcome {
        let base = json!({"group": c.group.get(), "message": c.message.get(), "ordinal": c.ordinal,
            "index": c.index, "window": c.window, "head": c.head, "old": c.old});
        let reference = match self
            .archive
            .media_ref(c.group, c.message, MediaKind::Image, c.index as u32)
            .await
        {
            Ok(Some(r)) => MediaRef {
                key: r.key,
                url: r.url,
                file: r.file,
                size: r.size,
            },
            other => {
                self.log(json!({"item": base, "outcome": "unrecoverable", "why": format!("no reference: {other:?}")}));
                return Outcome::Unrecoverable;
            }
        };
        let bytes = match self.fetcher.image(&reference, MAX_IMAGE_BYTES).await {
            Ok(bytes) => bytes,
            Err(error) => {
                self.log(
                    json!({"item": base, "outcome": "unrecoverable", "why": error.to_string()}),
                );
                return Outcome::Unrecoverable;
            }
        };
        if c.head {
            // The first call of a process saw its own picture, unless an earlier call of that
            // process uploaded and then failed; the model checks.
            match self.matches(&bytes, &c.old).await {
                Some(true) => {
                    self.log(json!({"item": base, "outcome": "accurate"}));
                    return Outcome::Accurate;
                }
                verdict => {
                    self.log(json!({"item": base, "check": format!("{verdict:?}")}));
                }
            }
        }
        let key = format!(
            "{}:{:x}",
            self.describer.fingerprint(),
            Sha256::digest(&bytes)
        );
        let new = match self.cache.get(&key).await {
            Ok(Some(found)) => found,
            _ => {
                match self
                    .describer
                    .describe(&bytes, qbot_media::sniff_mime(&bytes))
                    .await
                {
                    Ok(text) => {
                        let text = clean_description(&text);
                        if text.is_empty() {
                            self.log(json!({"item": base, "outcome": "unrecoverable", "why": "empty description"}));
                            return Outcome::Unrecoverable;
                        }
                        if let Err(error) = self.cache.put(&key, &text).await {
                            tracing::warn!(%error, "repair: description not cached");
                        }
                        text
                    }
                    Err(error) => {
                        self.log(json!({"item": base, "outcome": "unrecoverable", "why": error.to_string()}));
                        return Outcome::Unrecoverable;
                    }
                }
            }
        };
        let poisoned = format!("[image:{}]", c.old);
        let index = c.index;
        let replacement = format!("[image:{new}]");
        let rewritten = self
            .archive
            .rewrite_text(c.group, c.message, |text| {
                let current = nth_image_marker(text, index)?;
                (current == poisoned)
                    .then(|| fill(text, "image", index, &replacement))
                    .flatten()
            })
            .await;
        match rewritten {
            Ok(true) => {
                self.log(json!({"item": base, "outcome": "repaired", "new": new,
                    "repaired_ms": self.clock.now().get()}));
                Outcome::Repaired
            }
            Ok(false) => {
                self.log(json!({"item": base, "outcome": "changed"}));
                Outcome::Changed
            }
            Err(error) => {
                self.log(
                    json!({"item": base, "outcome": "unrecoverable", "why": error.to_string()}),
                );
                Outcome::Unrecoverable
            }
        }
    }

    /// Repaired ordinals by group, with when each was repaired, from the log of every run.
    fn repaired(&self) -> Result<BTreeMap<i64, BTreeMap<u64, i64>>, String> {
        let path = self.data_dir.join("repair-images.jsonl");
        let text = std::fs::read_to_string(&path).map_err(|e| e.to_string())?;
        let mut out: BTreeMap<i64, BTreeMap<u64, i64>> = BTreeMap::new();
        for line in text.lines() {
            let Ok(entry) = serde_json::from_str::<serde_json::Value>(line) else {
                continue;
            };
            if entry["outcome"] != "repaired" {
                continue;
            }
            let (Some(group), Some(ordinal), Some(at)) = (
                entry["item"]["group"].as_i64(),
                entry["item"]["ordinal"].as_u64(),
                entry["repaired_ms"].as_i64(),
            ) else {
                continue;
            };
            let slot = out.entry(group).or_default().entry(ordinal).or_insert(at);
            *slot = (*slot).max(at);
        }
        Ok(out)
    }

    async fn memory(&self) -> Result<(), String> {
        for (group, repaired) in self.repaired()? {
            let group = GroupId::new(group).map_err(|e| e.to_string())?;
            let last: i64 = sqlx::query_scalar(
                "SELECT coalesce(max(ordinal), 0) FROM chat_line WHERE group_id = $1",
            )
            .bind(group.get())
            .fetch_one(&self.pool)
            .await
            .map_err(|e| e.to_string())?;
            let last = u64::try_from(last).map_err(|e| e.to_string())?;
            let episodes = sqlx::query(
                "SELECT episode_id, first_ordinal, last_ordinal, created_ms FROM episode \
                 WHERE group_id = $1 ORDER BY first_ordinal",
            )
            .bind(group.get())
            .fetch_all(&self.pool)
            .await
            .map_err(|e| e.to_string())?;
            // An episode depends on its target and on the context it was extracted with; it is
            // stale when such a line was rewritten after the episode was made.
            let mut stale: Vec<(i64, std::ops::RangeInclusive<u64>)> = Vec::new();
            for row in &episodes {
                let (first, last_o): (i64, i64) =
                    (row.get("first_ordinal"), row.get("last_ordinal"));
                let (first, last_o) = (first as u64, last_o as u64);
                let made: i64 = row.get("created_ms");
                let plan = self
                    .slices
                    .next(first - 1, last)
                    .ok_or_else(|| format!("episode at {first} cannot be planned"))?;
                let from = plan.previous.as_ref().map_or(first, |r| *r.start());
                let to = plan.next.as_ref().map_or(last_o, |r| *r.end());
                if repaired.range(from..=to).any(|(_, at)| *at > made) {
                    stale.push((row.get("episode_id"), first..=last_o));
                }
            }
            if stale.is_empty() {
                self.log(json!({"phase": "memory", "group": group.get(), "rebuilt": 0}));
                continue;
            }
            let from = *stale[0].1.start();
            let stale_ids: Vec<i64> = stale.iter().map(|(id, _)| *id).collect();
            let ranges: Vec<_> = stale.iter().map(|(_, r)| r.clone()).collect();
            let undo = undo_tail(self.pool.clone(), group, from, stale_ids.clone());
            let rebuilt = self
                .jobs
                .repair_group(group, &ranges, undo)
                .await
                .map_err(|e| e.0)?;
            self.log(json!({"phase": "memory", "group": group.get(), "rebuilt": rebuilt,
                "episodes": stale_ids, "ranges": ranges.iter().map(|r| [*r.start(), *r.end()]).collect::<Vec<_>>(),
                "tail_from": from}));
        }
        Ok(())
    }
}

async fn find_candidates(pool: &PgPool) -> Result<Vec<Candidate>, String> {
    let rows = sqlx::query(
        "WITH gen AS (\
           SELECT description, min(created_ms) AS made FROM media_cache \
           WHERE key ~ '^(p|h):' GROUP BY description), \
         ranked AS (\
           SELECT description, made, \
             width_bucket(made, $1::bigint[]) AS w, \
             row_number() OVER (PARTITION BY width_bucket(made, $1::bigint[]) ORDER BY made) AS rn \
           FROM gen WHERE made < $2) \
         SELECT l.group_id, l.message_id, l.ordinal, m.ord - 1 AS idx, m.t[1] AS old, r.w, r.rn = 1 AS head \
         FROM chat_line l \
         CROSS JOIN LATERAL regexp_matches(l.text, '\\[image(?::([^\\]]*))?\\]', 'g') WITH ORDINALITY m(t, ord) \
         JOIN ranked r ON r.description = m.t[1] \
         ORDER BY l.group_id, l.ordinal, idx",
    )
    .bind(&RESTARTS[..4])
    .bind(RESTARTS[4])
    .fetch_all(pool)
    .await
    .map_err(|e| e.to_string())?;
    rows.iter()
        .map(|r| {
            Ok(Candidate {
                group: GroupId::new(r.get("group_id")).map_err(|e| e.to_string())?,
                message: MessageId::new(r.get("message_id")).map_err(|e| e.to_string())?,
                ordinal: u64::try_from(r.get::<i64, _>("ordinal")).map_err(|e| e.to_string())?,
                index: usize::try_from(r.get::<i64, _>("idx")).map_err(|e| e.to_string())?,
                old: r.get("old"),
                window: usize::try_from(r.get::<i32, _>("w")).map_err(|e| e.to_string())?,
                head: r.get("head"),
            })
        })
        .collect()
}

/// The text of the `index`-th image marker (`[image]` or `[image:...]`) of a line.
fn nth_image_marker(text: &str, index: usize) -> Option<String> {
    let mut seen = 0;
    let mut at = 0;
    while let Some(found) = text[at..].find("[image") {
        let start = at + found;
        let rest = &text[start..];
        let len = if rest.starts_with("[image]") {
            7
        } else if rest.starts_with("[image:") {
            rest.find(']')? + 1
        } else {
            at = start + 6;
            continue;
        };
        if seen == index {
            return Some(rest[..len].to_owned());
        }
        seen += 1;
        at = start + len;
    }
    None
}

/// Undo, in one transaction, what the group's episodes from ordinal `from` on contributed to
/// facts, group knowledge and names, delete the `stale` episodes and mark the rest of that tail
/// unconsolidated. Every such effect carries the time of its episode's end, which is later than
/// every episode before the tail.
async fn undo_tail(pool: PgPool, group: GroupId, from: u64, stale: Vec<i64>) -> Result<(), String> {
    let e = |e: sqlx::Error| e.to_string();
    let g = group.get();
    let from = i64::try_from(from).map_err(|e| e.to_string())?;
    let mut tx = pool.begin().await.map_err(e)?;
    sqlx::query("SELECT pg_advisory_xact_lock(hashtextextended('fact:' || $1::text, 0))")
        .bind(g)
        .execute(&mut *tx)
        .await
        .map_err(e)?;
    let tail: Vec<i64> = sqlx::query_scalar(
        "SELECT episode_id FROM episode WHERE group_id = $1 AND first_ordinal >= $2",
    )
    .bind(g)
    .bind(from)
    .fetch_all(&mut *tx)
    .await
    .map_err(e)?;
    let cutoff: i64 = sqlx::query_scalar(
        "SELECT coalesce(max(ended_ms), 0) FROM episode WHERE group_id = $1 AND first_ordinal < $2",
    )
    .bind(g)
    .bind(from)
    .fetch_one(&mut *tx)
    .await
    .map_err(e)?;
    let tail_min: i64 = sqlx::query_scalar(
        "SELECT coalesce(min(ended_ms), 0) FROM episode WHERE group_id = $1 AND first_ordinal >= $2",
    )
    .bind(g)
    .bind(from)
    .fetch_one(&mut *tx)
    .await
    .map_err(e)?;
    if tail_min <= cutoff {
        return Err(format!(
            "group {g}: the tail does not end after the kept episodes ({tail_min} <= {cutoff})"
        ));
    }

    // Facts and group knowledge.
    let touched: Vec<i64> = sqlx::query_scalar(
        "DELETE FROM fact_evidence WHERE episode_id = ANY($1) AND fact_id IN (SELECT fact_id FROM fact WHERE group_id = $2) RETURNING fact_id",
    )
    .bind(&tail)
    .bind(g)
    .fetch_all(&mut *tx)
    .await
    .map_err(e)?;
    let touched: Vec<i64> = touched
        .into_iter()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    let kept_forgotten: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM fact f WHERE f.fact_id = ANY($1) AND f.status = 'forgotten' \
         AND NOT EXISTS (SELECT 1 FROM fact_evidence x WHERE x.fact_id = f.fact_id)",
    )
    .bind(&touched)
    .fetch_one(&mut *tx)
    .await
    .map_err(e)?;
    let removed_facts = sqlx::query(
        "DELETE FROM fact f WHERE f.fact_id = ANY($1) AND f.status <> 'forgotten' \
         AND NOT EXISTS (SELECT 1 FROM fact_evidence x WHERE x.fact_id = f.fact_id)",
    )
    .bind(&touched)
    .execute(&mut *tx)
    .await
    .map_err(e)?
    .rows_affected();
    sqlx::query(
        "UPDATE fact f SET supports = s.n, last_confirmed_ms = s.last FROM (\
           SELECT x.fact_id, count(*)::int AS n, max(ep.ended_ms) AS last FROM fact_evidence x \
           JOIN episode ep ON ep.episode_id = x.episode_id WHERE x.fact_id = ANY($1) GROUP BY x.fact_id) s \
         WHERE f.fact_id = s.fact_id",
    )
    .bind(&touched)
    .execute(&mut *tx)
    .await
    .map_err(e)?;
    let reactivated = sqlx::query(
        "UPDATE fact SET status = 'active', ended_ms = NULL \
         WHERE group_id = $1 AND status = 'superseded' AND ended_ms > $2",
    )
    .bind(g)
    .bind(cutoff)
    .execute(&mut *tx)
    .await
    .map_err(e)?
    .rows_affected();

    // Names.
    let aliases: Vec<i64> = sqlx::query_scalar(
        "DELETE FROM alias_evidence WHERE kind = 'extracted' AND support = ANY($1) \
         AND alias_id IN (SELECT alias_id FROM alias WHERE group_id = $2) RETURNING alias_id",
    )
    .bind(&tail)
    .bind(g)
    .fetch_all(&mut *tx)
    .await
    .map_err(e)?;
    let aliases: BTreeSet<i64> = aliases.into_iter().collect();
    let policy = IdentityPolicy::default();
    let (mut removed_aliases, mut updated_aliases) = (0, 0);
    for alias in &aliases {
        let rows =
            sqlx::query("SELECT kind, support, at_ms FROM alias_evidence WHERE alias_id = $1")
                .bind(alias)
                .fetch_all(&mut *tx)
                .await
                .map_err(e)?;
        if rows.is_empty() {
            sqlx::query("DELETE FROM alias WHERE alias_id = $1")
                .bind(alias)
                .execute(&mut *tx)
                .await
                .map_err(e)?;
            removed_aliases += 1;
            continue;
        }
        let records: Vec<EvidenceRecord> = rows
            .iter()
            .map(|r| EvidenceRecord {
                kind: if r.get::<String, _>("kind") == "manual" {
                    EvidenceKind::Manual
                } else {
                    EvidenceKind::Extracted
                },
                support: r.get("support"),
            })
            .collect();
        let last = rows
            .iter()
            .map(|r| r.get::<i64, _>("at_ms"))
            .max()
            .unwrap_or(0);
        let conf = confidence(&records);
        let status = match status_for(conf, &policy) {
            qbot_memory::identity::AliasStatus::Confirmed => "confirmed",
            _ => "candidate",
        };
        sqlx::query(
            "UPDATE alias SET confidence = $2, last_evidence_ms = $3, \
             status = CASE WHEN removed THEN 'inactive' ELSE $4 END WHERE alias_id = $1",
        )
        .bind(alias)
        .bind(conf)
        .bind(last)
        .bind(status)
        .execute(&mut *tx)
        .await
        .map_err(e)?;
        updated_aliases += 1;
    }

    // Episodes: the stale ones go (their vectors with them), the rest of the tail is applied
    // again in order after the rebuild.
    sqlx::query("DELETE FROM episode WHERE episode_id = ANY($1) AND group_id = $2")
        .bind(&stale)
        .bind(g)
        .execute(&mut *tx)
        .await
        .map_err(e)?;
    sqlx::query(
        "UPDATE episode SET consolidated_ms = NULL WHERE group_id = $1 AND first_ordinal >= $2",
    )
    .bind(g)
    .bind(from)
    .execute(&mut *tx)
    .await
    .map_err(e)?;
    tx.commit().await.map_err(e)?;
    tracing::info!(
        group = g,
        tail = tail.len(),
        stale = stale.len(),
        facts_touched = touched.len(),
        removed_facts,
        reactivated,
        kept_forgotten,
        removed_aliases,
        updated_aliases,
        "repair: memory of the tail undone"
    );
    Ok(())
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used)]
mod rehearsal {
    use super::*;
    use qbot_memory::consolidate::Consolidator;
    use qbot_memory::predicates::Predicates;
    use qbot_memory::{BuilderConfig, EpisodeBuilder, EpisodeExtractor};
    use qbot_store::{PgEpisodeStore, PgFactStore, PgIdentityStore};

    /// Facts, fact evidence, names and name evidence of a group as comparable text, without ids.
    async fn snapshot(pool: &PgPool, group: i64) -> Vec<String> {
        let mut out: Vec<String> = sqlx::query_scalar(
            "SELECT concat_ws('|', 'fact', coalesce(subject_account, 0), predicate, key, object, label, status, \
               supports, decay, first_seen_ms, last_confirmed_ms, ended_ms, \
               (SELECT string_agg(x.episode_id || ':' || x.message_id || ':' || x.quote, ',' ORDER BY x.episode_id) \
                FROM fact_evidence x WHERE x.fact_id = f.fact_id)) FROM fact f WHERE group_id = $1",
        )
        .bind(group)
        .fetch_all(pool)
        .await
        .unwrap();
        out.extend(
            sqlx::query_scalar::<_, String>(
                "SELECT concat_ws('|', 'alias', text, target_kind, target_account, target_holder, status, \
                   round(confidence::numeric, 4), removed, last_evidence_ms, \
                   (SELECT string_agg(e.kind || ':' || coalesce(e.support, -1) || ':' || e.at_ms, ',' ORDER BY e.kind, e.support) \
                    FROM alias_evidence e WHERE e.alias_id = a.alias_id)) FROM alias a WHERE group_id = $1",
            )
            .bind(group)
            .fetch_all(pool)
            .await
            .unwrap(),
        );
        out.sort();
        out
    }

    fn jobs_grid() -> SliceGrid {
        SliceGrid::for_window(qbot_core::HistoryWindow::default(), 3)
    }

    /// Against a restored copy of production (`QBOT_REHEARSAL_URL`): finds the candidates, then
    /// for every group with one, undoes its tail and applies the same findings again without
    /// extracting anything; facts and names must come back exactly.
    #[tokio::test]
    #[ignore = "needs a restored production copy"]
    async fn undoing_and_reapplying_a_tail_restores_memory_exactly() {
        let url = std::env::var("QBOT_REHEARSAL_URL").expect("QBOT_REHEARSAL_URL");
        let pool = PgPool::connect(&url).await.unwrap();
        let clock: Arc<dyn Clock> = Arc::new(qbot_core::SystemClock);
        let candidates = find_candidates(&pool).await.unwrap();
        let heads = candidates.iter().filter(|c| c.head).count();
        eprintln!("candidates: {} (heads {heads})", candidates.len());
        for c in &candidates {
            assert_eq!(
                nth_image_marker(
                    &sqlx::query_scalar::<_, String>(
                        "SELECT text FROM chat_line WHERE group_id = $1 AND message_id = $2"
                    )
                    .bind(c.group.get())
                    .bind(c.message.get())
                    .fetch_one(&pool)
                    .await
                    .unwrap(),
                    c.index
                ),
                Some(format!("[image:{}]", c.old)),
                "marker position of {c:?}"
            );
        }
        let jobs = EpisodeJobs::new(
            Arc::new(PgEpisodeStore::new(pool.clone(), clock.clone())),
            EpisodeBuilder::new(
                EpisodeExtractor::new(Arc::new(qbot_llm::fake::FakeProvider::new([]))),
                Arc::new(qbot_llm::FakeEmbedder::new(8)),
                BuilderConfig {
                    language: "English".into(),
                },
            ),
            jobs_grid(),
        )
        .with_consolidator(Arc::new(Consolidator::new(
            Arc::new(PgFactStore::new(pool.clone())),
            Arc::new(PgIdentityStore::new(
                pool.clone(),
                IdentityPolicy::default(),
            )),
            Arc::new(Predicates::builtin()),
        )));
        let mut groups: BTreeMap<i64, u64> = BTreeMap::new();
        for c in &candidates {
            let slot = groups.entry(c.group.get()).or_insert(c.ordinal);
            *slot = (*slot).min(c.ordinal);
        }
        for (group, first_poisoned) in groups {
            let from: Option<i64> = sqlx::query_scalar(
                "SELECT min(first_ordinal) FROM episode WHERE group_id = $1 AND last_ordinal + 30 >= $2",
            )
            .bind(group)
            .bind(i64::try_from(first_poisoned).unwrap())
            .fetch_one(&pool)
            .await
            .unwrap();
            let Some(from) = from else {
                eprintln!("group {group}: no episode depends on line {first_poisoned}");
                continue;
            };
            let last: i64 =
                sqlx::query_scalar("SELECT max(ordinal) FROM chat_line WHERE group_id = $1")
                    .bind(group)
                    .fetch_one(&pool)
                    .await
                    .unwrap();
            let ranges: Vec<(i64, i64)> = sqlx::query_as(
                "SELECT first_ordinal, last_ordinal FROM episode WHERE group_id = $1 AND first_ordinal >= $2",
            )
            .bind(group)
            .bind(from)
            .fetch_all(&pool)
            .await
            .unwrap();
            for (first, last_o) in &ranges {
                let plan = jobs_grid().next(*first as u64 - 1, last as u64).unwrap();
                assert_eq!(plan.target, *first as u64..=*last_o as u64, "group {group}");
            }
            eprintln!(
                "group {group}: {} tail slices re-plan to their ranges",
                ranges.len()
            );
            let before = snapshot(&pool, group).await;
            let g = GroupId::new(group).unwrap();
            let undo = undo_tail(pool.clone(), g, u64::try_from(from).unwrap(), Vec::new());
            jobs.repair_group(g, &[], undo).await.unwrap();
            let after = snapshot(&pool, group).await;
            let lost: Vec<_> = before.iter().filter(|r| !after.contains(r)).collect();
            let gained: Vec<_> = after.iter().filter(|r| !before.contains(r)).collect();
            eprintln!(
                "group {group}: tail from {from}, {} records, lost {lost:#?} gained {gained:#?}",
                before.len()
            );
            assert!(
                lost.is_empty() && gained.is_empty(),
                "group {group} changed"
            );
        }
    }
}
